// Default file functions
#ifndef LINEARUI_DISABLE_DEFAULT_FILE_FUNCTIONS

LinearFileHandle LinearFileOpen(const char* filename, const char* mode)
{
#if defined(_WIN32) && !defined(LINEARUI_DISABLE_WIN32_FUNCTIONS) && (defined(__MINGW32__) || (!defined(__CYGWIN__) && !defined(__GNUC__)))
    // We need a fopen() wrapper because MSVC/Windows fopen doesn't handle UTF-8 filenames.
    // Previously we used LinearTextCountCharsFromUtf8/LinearTextStrFromUtf8 here but we now need to support LinearWchar16 and LinearWchar32!
    const int filename_wsize = ::MultiByteToWideChar(CP_UTF8, 0, filename, -1, NULL, 0);
    const int mode_wsize = ::MultiByteToWideChar(CP_UTF8, 0, mode, -1, NULL, 0);

    // Use stack buffer if possible, otherwise heap buffer. Sizes include zero terminator.
    // We don't rely on current LinearUIContext as this is implied to be a helper function which doesn't depend on it (see #7314).
    wchar_t local_temp_stack[FILENAME_MAX];
    LinearVector<wchar_t> local_temp_heap;
    if (filename_wsize + mode_wsize > LINEARUI_COUNTOF(local_temp_stack))
        local_temp_heap.resize(filename_wsize + mode_wsize);
    wchar_t* filename_wbuf = local_temp_heap.Data ? local_temp_heap.Data : local_temp_stack;
    wchar_t* mode_wbuf = filename_wbuf + filename_wsize;
    ::MultiByteToWideChar(CP_UTF8, 0, filename, -1, filename_wbuf, filename_wsize);
    ::MultiByteToWideChar(CP_UTF8, 0, mode, -1, mode_wbuf, mode_wsize);
    return ::_wfopen(filename_wbuf, mode_wbuf);
#else
    return fopen(filename, mode);
#endif
}

// We should in theory be using fseeko()/ftello() with off_t and _fseeki64()/_ftelli64() with __int64, waiting for the PR that does that in a very portable pre-C++11 zero-warnings way.
bool    LinearFileClose(LinearFileHandle f)     { return fclose(f) == 0; }
LinearU64   LinearFileGetSize(LinearFileHandle f)   { long off = 0, sz = 0; return ((off = ftell(f)) != -1 && !fseek(f, 0, SEEK_END) && (sz = ftell(f)) != -1 && !fseek(f, off, SEEK_SET)) ? (LinearU64)sz : (LinearU64)-1; }
LinearU64   LinearFileRead(void* data, LinearU64 sz, LinearU64 count, LinearFileHandle f)           { return fread(data, (size_t)sz, (size_t)count, f); }
LinearU64   LinearFileWrite(const void* data, LinearU64 sz, LinearU64 count, LinearFileHandle f)    { return fwrite(data, (size_t)sz, (size_t)count, f); }
#endif // #ifndef LINEARUI_DISABLE_DEFAULT_FILE_FUNCTIONS

// Helper: Load file content into memory
// Memory allocated with LINEARUI_ALLOC(), must be freed by user using LINEARUI_FREE() == LinearUI::MemFree()
// This can't really be used with "rt" because fseek size won't match read size.
void*   LinearFileLoadToMemory(const char* filename, const char* mode, size_t* out_file_size, int padding_bytes)
{
    LINEARUI_ASSERT(filename && mode);
    if (out_file_size)
        *out_file_size = 0;

    LinearFileHandle f;
    if ((f = LinearFileOpen(filename, mode)) == NULL)
        return NULL;

    size_t file_size = (size_t)LinearFileGetSize(f);
    if (file_size == (size_t)-1)
    {
        LinearFileClose(f);
        return NULL;
    }

    void* file_data = LINEARUI_ALLOC(file_size + padding_bytes);
    if (file_data == NULL)
    {
        LinearFileClose(f);
        return NULL;
    }
    if (LinearFileRead(file_data, 1, file_size, f) != file_size)
    {
        LinearFileClose(f);
        LINEARUI_FREE(file_data);
        return NULL;
    }
    if (padding_bytes > 0)
        memset((void*)(((char*)file_data) + file_size), 0, (size_t)padding_bytes);

    LinearFileClose(f);
    if (out_file_size)
        *out_file_size = file_size;

    return file_data;
}

