const LinearUIStyleVarInfo* LinearUI::GetStyleVarInfo(LinearUIStyleVar idx)
{
    LINEARUI_ASSERT(idx >= 0 && idx < LinearUIStyleVar_COUNT);
    LINEARUI_STATIC_ASSERT(LINEARUI_COUNTOF(GStyleVarsInfo) == LinearUIStyleVar_COUNT);
    return &GStyleVarsInfo[idx];
}

void LinearUI::PushStyleVar(LinearUIStyleVar idx, float val)
{
    LinearUIContext& g = *GLinearUI;
    const LinearUIStyleVarInfo* var_info = GetStyleVarInfo(idx);
    LINEARUI_ASSERT_USER_ERROR_RET(var_info->DataType == LinearUIDataType_Float && var_info->Count == 1, "Calling PushStyleVar() variant with wrong type!");
    float* pvar = (float*)var_info->GetVarPtr(&g.Style);
    g.StyleVarStack.push_back(LinearUIStyleMod(idx, *pvar));
    *pvar = val;
}

void LinearUI::PushStyleVarX(LinearUIStyleVar idx, float val_x)
{
    LinearUIContext& g = *GLinearUI;
    const LinearUIStyleVarInfo* var_info = GetStyleVarInfo(idx);
    LINEARUI_ASSERT_USER_ERROR_RET(var_info->DataType == LinearUIDataType_Float && var_info->Count == 2, "Calling PushStyleVar() variant with wrong type!");
    LinearVec2* pvar = (LinearVec2*)var_info->GetVarPtr(&g.Style);
    g.StyleVarStack.push_back(LinearUIStyleMod(idx, *pvar));
    pvar->x = val_x;
}

void LinearUI::PushStyleVarY(LinearUIStyleVar idx, float val_y)
{
    LinearUIContext& g = *GLinearUI;
    const LinearUIStyleVarInfo* var_info = GetStyleVarInfo(idx);
    LINEARUI_ASSERT_USER_ERROR_RET(var_info->DataType == LinearUIDataType_Float && var_info->Count == 2, "Calling PushStyleVar() variant with wrong type!");
    LinearVec2* pvar = (LinearVec2*)var_info->GetVarPtr(&g.Style);
    g.StyleVarStack.push_back(LinearUIStyleMod(idx, *pvar));
    pvar->y = val_y;
}

void LinearUI::PushStyleVar(LinearUIStyleVar idx, const LinearVec2& val)
{
    LinearUIContext& g = *GLinearUI;
    const LinearUIStyleVarInfo* var_info = GetStyleVarInfo(idx);
    LINEARUI_ASSERT_USER_ERROR_RET(var_info->DataType == LinearUIDataType_Float && var_info->Count == 2, "Calling PushStyleVar() variant with wrong type!");
    LinearVec2* pvar = (LinearVec2*)var_info->GetVarPtr(&g.Style);
    g.StyleVarStack.push_back(LinearUIStyleMod(idx, *pvar));
    *pvar = val;
}

void LinearUI::PopStyleVar(int count)
{
    LinearUIContext& g = *GLinearUI;
    if (g.StyleVarStack.Size < count)
    {
        LINEARUI_ASSERT_USER_ERROR(0, "Calling PopStyleVar() too many times!");
        count = g.StyleVarStack.Size;
    }
    while (count > 0)
    {
        // We avoid a generic memcpy(data, &backup.Backup.., GDataTypeSize[info->Type] * info->Count), the overhead in Debug is not worth it.
        LinearUIStyleMod& backup = g.StyleVarStack.back();
        const LinearUIStyleVarInfo* var_info = GetStyleVarInfo(backup.VarIdx);
        void* data = var_info->GetVarPtr(&g.Style);
        if (var_info->DataType == LinearUIDataType_Float && var_info->Count == 1)      { ((float*)data)[0] = backup.BackupFloat[0]; }
        else if (var_info->DataType == LinearUIDataType_Float && var_info->Count == 2) { ((float*)data)[0] = backup.BackupFloat[0]; ((float*)data)[1] = backup.BackupFloat[1]; }
        g.StyleVarStack.pop_back();
        count--;
    }
}

