//-----------------------------------------------------------------------------
// [SECTION] RENDER HELPERS
// Some of those (internal) functions are currently quite a legacy mess - their signature and behavior will change,
// we need a nicer separation between low-level functions and high-level functions relying on the LinearUI context.
// Also see linearui_draw.cpp for some more which have been reworked to not rely on LinearUI:: context.
//-----------------------------------------------------------------------------

const char* LinearUI::FindRenderedTextEnd(const char* text, const char* text_end)
{
    const char* text_display_end = text;
    if (!text_end)
        text_end = (const char*)-1;

    while (text_display_end < text_end && *text_display_end != '\0' && (text_display_end[0] != '#' || text_display_end[1] != '#'))
        text_display_end++;
    return text_display_end;
}

// Internal LinearUI functions to render text
// RenderText***() functions calls LinearDrawList::AddText() calls LinearBitmapFont::RenderText()
void LinearUI::RenderText(LinearVec2 pos, const char* text, const char* text_end, bool hide_text_after_hash)
{
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;

    // Hide anything after a '##' string
    const char* text_display_end;
    if (hide_text_after_hash)
    {
        text_display_end = FindRenderedTextEnd(text, text_end);
    }
    else
    {
        if (!text_end)
            text_end = text + LinearStrlen(text); // FIXME-OPT (not reached by our internal calls)
        text_display_end = text_end;
    }

    if (text != text_display_end)
    {
        window->DrawList->AddText(g.Font, g.FontSize, pos, GetColorU32(LinearUICol_Text), text, text_display_end);
        if (g.LogEnabled)
            LogRenderedText(&pos, text, text_display_end);
    }
}

void LinearUI::RenderTextWrapped(LinearVec2 pos, const char* text, const char* text_end, float wrap_width)
{
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;

    if (!text_end)
        text_end = text + LinearStrlen(text); // FIXME-OPT (not reached by our internal calls)

    if (text != text_end)
    {
        window->DrawList->AddText(g.Font, g.FontSize, pos, GetColorU32(LinearUICol_Text), text, text_end, wrap_width);
        if (g.LogEnabled)
            LogRenderedText(&pos, text, text_end);
    }
}

// Default clip_rect uses (pos_min,pos_max)
// Handle clipping on CPU immediately (vs typically let the GPU clip the triangles that are overlapping the clipping rectangle edges)
// FIXME-OPT: Since we have or calculate text_size we could coarse clip whole block immediately, especially for text above draw_list->DrawList.
// Effectively as this is called from widget doing their own coarse clipping it's not very valuable presently. Next time function will take
// better advantage of the render function taking size into account for coarse clipping.
void LinearUI::RenderTextClippedEx(LinearDrawList* draw_list, const LinearVec2& pos_min, const LinearVec2& pos_max, const char* text, const char* text_display_end, const LinearVec2* text_size_if_known, const LinearVec2& align, const LinearRect* clip_rect)
{
    // Perform CPU side clipping for single clipped element to avoid using scissor state
    LinearVec2 pos = pos_min;
    const LinearVec2 text_size = text_size_if_known ? *text_size_if_known : CalcTextSize(text, text_display_end, false, 0.0f);

    const LinearVec2* clip_min = clip_rect ? &clip_rect->Min : &pos_min;
    const LinearVec2* clip_max = clip_rect ? &clip_rect->Max : &pos_max;
    bool need_clipping = (pos.x + text_size.x >= clip_max->x) || (pos.y + text_size.y >= clip_max->y);
    if (clip_rect) // If we had no explicit clipping rectangle then pos==clip_min
        need_clipping |= (pos.x < clip_min->x) || (pos.y < clip_min->y);

    // Align whole block. We should defer that to the better rendering function when we'll have support for individual line alignment.
    if (align.x > 0.0f) pos.x = LinearMax(pos.x, pos.x + (pos_max.x - pos.x - text_size.x) * align.x);
    if (align.y > 0.0f) pos.y = LinearMax(pos.y, pos.y + (pos_max.y - pos.y - text_size.y) * align.y);

    // Render
    if (need_clipping)
    {
        LinearVec4 fine_clip_rect(clip_min->x, clip_min->y, clip_max->x, clip_max->y);
        draw_list->AddText(NULL, 0.0f, pos, GetColorU32(LinearUICol_Text), text, text_display_end, 0.0f, &fine_clip_rect);
    }
    else
    {
        draw_list->AddText(NULL, 0.0f, pos, GetColorU32(LinearUICol_Text), text, text_display_end, 0.0f, NULL);
    }
}

void LinearUI::RenderTextClipped(const LinearVec2& pos_min, const LinearVec2& pos_max, const char* text, const char* text_end, const LinearVec2* text_size_if_known, const LinearVec2& align, const LinearRect* clip_rect)
{
    // Hide anything after a '##' string
    const char* text_display_end = FindRenderedTextEnd(text, text_end);
    const int text_len = (int)(text_display_end - text);
    if (text_len == 0)
        return;

    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;
    RenderTextClippedEx(window->DrawList, pos_min, pos_max, text, text_display_end, text_size_if_known, align, clip_rect);
    if (g.LogEnabled)
        LogRenderedText(&pos_min, text, text_display_end);
}

// Another overly complex function until we reorganize everything into a nice all-in-one helper.
// This is made more complex because we have dissociated the layout rectangle (pos_min..pos_max) from 'ellipsis_max_x' which may be beyond it.
// This is because in the context of tabs we selectively hide part of the text when the Close Button appears, but we don't want the ellipsis to move.
// (BREAKING) On 2025/04/16 we removed the 'float clip_max_x' parameters which was preceding 'float ellipsis_max' and was the same value for 99% of users.
void LinearUI::RenderTextEllipsis(LinearDrawList* draw_list, const LinearVec2& pos_min, const LinearVec2& pos_max, float ellipsis_max_x, const char* text, const char* text_end_full, const LinearVec2* text_size_if_known)
{
    LinearUIContext& g = *GLinearUI;
    if (text_end_full == NULL)
        text_end_full = FindRenderedTextEnd(text);
    const LinearVec2 text_size = text_size_if_known ? *text_size_if_known : CalcTextSize(text, text_end_full, false, 0.0f);

    //draw_list->AddLineV(pos_max.x, pos_min.y - 4, pos_max.y + 6, LINEARUI_COL32(0, 0, 255, 255));
    //draw_list->AddLineV(ellipsis_max_x, pos_min.y - 2, pos_max.y + 3, LINEARUI_COL32(0, 255, 0, 255));

    // FIXME: We could technically remove (last_glyph->AdvanceX - last_glyph->X1) from text_size.x here and save a few pixels.
    if (text_size.x > pos_max.x - pos_min.x)
    {
        // Hello wo...
        // |       |   |
        // min   max   ellipsis_max
        //          <-> this is generally some padding value

        LinearFont* font = draw_list->_Data->Font;
        const float font_size = draw_list->_Data->FontSize;
        const float font_scale = draw_list->_Data->FontScale;
        const char* text_end_ellipsis = NULL;
        LinearFontBaked* baked = font->GetFontBaked(font_size);
        const float ellipsis_width = baked->GetCharAdvance(font->EllipsisChar) * font_scale;

        // We can now claim the space between pos_max.x and ellipsis_max.x
        const float text_avail_width = LinearMax((LinearMax(pos_max.x, ellipsis_max_x) - ellipsis_width) - pos_min.x, 1.0f);
        const float text_size_clipped_x = font->CalcTextSizeA(font_size, text_avail_width, 0.0f, text, text_end_full, &text_end_ellipsis).x;

        // Render text, render ellipsis
        RenderTextClippedEx(draw_list, pos_min, pos_max, text, text_end_ellipsis, &text_size, LinearVec2(0.0f, 0.0f));
        LinearVec4 cpu_fine_clip_rect(pos_min.x, pos_min.y, pos_max.x, pos_max.y);
        LinearVec2 ellipsis_pos = LinearTrunc(LinearVec2(pos_min.x + text_size_clipped_x, pos_min.y));
        font->RenderChar(draw_list, font_size, ellipsis_pos, GetColorU32(LinearUICol_Text), font->EllipsisChar, &cpu_fine_clip_rect);
    }
    else
    {
        RenderTextClippedEx(draw_list, pos_min, pos_max, text, text_end_full, &text_size, LinearVec2(0.0f, 0.0f));
    }

    if (g.LogEnabled)
        LogRenderedText(&pos_min, text, text_end_full);
}

// Render a rectangle shaped with optional rounding and borders
void LinearUI::RenderFrame(LinearVec2 p_min, LinearVec2 p_max, LinearU32 fill_col, bool borders, float rounding)
{
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;
    window->DrawList->AddRectFilled(p_min, p_max, fill_col, rounding);
    const float border_size = g.Style.FrameBorderSize;
    if (borders && border_size > 0.0f)
    {
        window->DrawList->AddRect(p_min + LinearVec2(1, 1), p_max + LinearVec2(1, 1), GetColorU32(LinearUICol_BorderShadow), rounding, border_size);
        window->DrawList->AddRect(p_min, p_max, GetColorU32(LinearUICol_Border), rounding, border_size);
    }
}

void LinearUI::RenderFrameBorder(LinearVec2 p_min, LinearVec2 p_max, float rounding)
{
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;
    const float border_size = g.Style.FrameBorderSize;
    if (border_size > 0.0f)
    {
        window->DrawList->AddRect(p_min + LinearVec2(1, 1), p_max + LinearVec2(1, 1), GetColorU32(LinearUICol_BorderShadow), rounding, border_size);
        window->DrawList->AddRect(p_min, p_max, GetColorU32(LinearUICol_Border), rounding, border_size);
    }
}

void LinearUI::RenderColorComponentMarker(const LinearRect& bb, LinearU32 col, float rounding)
{
    if (bb.Min.x + 1 >= bb.Max.x)
        return;
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;
    RenderRectFilledInRangeH(window->DrawList, bb, col, bb.Min.x, LinearMin(bb.Min.x + g.Style.ColorMarkerSize, bb.Max.x), rounding);
}

void LinearUI::RenderNavCursor(const LinearRect& bb, LinearUIID id, LinearUINavRenderCursorFlags flags)
{
    LinearUIContext& g = *GLinearUI;
    if (id != g.NavId)
        return;
    if (!g.NavCursorVisible && !(flags & LinearUINavRenderCursorFlags_AlwaysDraw))
        return;
    if (id == g.LastItemData.ID && (g.LastItemData.ItemFlags & LinearUIItemFlags_NoNav))
        return;

    // We don't early out on 'window->Flags & LinearUIWindowFlags_NoNavInputs' because it would be inconsistent with
    // other code directly checking NavCursorVisible. Instead we aim for NavCursorVisible to always be false.
    LinearUIWindow* window = g.CurrentWindow;
    if (window->DC.NavHideHighlightOneFrame)
        return;

    float rounding = (flags & LinearUINavRenderCursorFlags_NoRounding) ? 0.0f : g.Style.FrameRounding;
    LinearRect display_rect = bb;
    display_rect.ClipWith(window->ClipRect);
    const float thickness = 2.0f;
    if (flags & LinearUINavRenderCursorFlags_Compact)
    {
        window->DrawList->AddRect(display_rect.Min, display_rect.Max, GetColorU32(LinearUICol_NavCursor), rounding, thickness);
    }
    else
    {
        const float distance = 3.0f + thickness * 0.5f;
        display_rect.Expand(LinearVec2(distance, distance));
        bool fully_visible = window->ClipRect.Contains(display_rect);
        if (!fully_visible)
            window->DrawList->PushClipRect(display_rect.Min, display_rect.Max);
        window->DrawList->AddRect(display_rect.Min, display_rect.Max, GetColorU32(LinearUICol_NavCursor), rounding, thickness);
        if (!fully_visible)
            window->DrawList->PopClipRect();
    }
}

void LinearUI::RenderMouseCursor(LinearVec2 base_pos, float base_scale, LinearUIMouseCursor mouse_cursor, LinearU32 col_fill, LinearU32 col_border, LinearU32 col_shadow)
{
    LinearUIContext& g = *GLinearUI;
    if (mouse_cursor <= LinearUIMouseCursor_None || mouse_cursor >= LinearUIMouseCursor_COUNT) // We intentionally accept out of bound values.
        mouse_cursor = LinearUIMouseCursor_Arrow;
    LinearFontAtlas* font_atlas = g.DrawListSharedData.FontAtlas;
    for (LinearUIViewportP* viewport : g.Viewports)
    {
        // We scale cursor with current viewport/monitor, however Windows 10 for its own hardware cursor seems to be using a different scale factor.
        LinearVec2 offset, size, uv[4];
        if (!LinearFontAtlasGetMouseCursorTexData(font_atlas, mouse_cursor, &offset, &size, &uv[0], &uv[2]))
            continue;
        const LinearVec2 pos = base_pos - offset;
        const float scale = base_scale * viewport->DpiScale;
        if (!viewport->GetMainRect().Overlaps(LinearRect(pos, pos + LinearVec2(size.x + 2, size.y + 2) * scale)))
            continue;
        LinearDrawList* draw_list = GetForegroundDrawList(viewport);
        LinearTextureRef tex_ref = font_atlas->TexRef;
        draw_list->PushTexture(tex_ref);
        draw_list->AddImage(tex_ref, pos + LinearVec2(1, 0) * scale, pos + (LinearVec2(1, 0) + size) * scale, uv[2], uv[3], col_shadow);
        draw_list->AddImage(tex_ref, pos + LinearVec2(2, 0) * scale, pos + (LinearVec2(2, 0) + size) * scale, uv[2], uv[3], col_shadow);
        draw_list->AddImage(tex_ref, pos,                        pos + size * scale,                  uv[2], uv[3], col_border);
        draw_list->AddImage(tex_ref, pos,                        pos + size * scale,                  uv[0], uv[1], col_fill);
        if (mouse_cursor == LinearUIMouseCursor_Wait || mouse_cursor == LinearUIMouseCursor_Progress)
        {
            float a_min = LinearFmod((float)g.Time * 5.0f, 2.0f * LINEARUI_PI);
            float a_max = a_min + LINEARUI_PI * 1.65f;
            draw_list->PathArcTo(pos + LinearVec2(14, -1) * scale, 6.0f * scale, a_min, a_max);
            draw_list->PathStroke(col_fill, 3.0f * scale);
        }
        draw_list->PopTexture();
    }
}

//-----------------------------------------------------------------------------
// [SECTION] INITIALIZATION, SHUTDOWN
//-----------------------------------------------------------------------------

// Internal state access - if you want to share Dear LinearUI state between modules (e.g. DLL) or allocate it yourself
// Note that we still point to some static data and members (such as GFontAtlas), so the state instance you end up using will point to the static data within its module
LinearUIContext* LinearUI::GetCurrentContext()
{
    return GLinearUI;
}

void LinearUI::SetCurrentContext(LinearUIContext* ctx)
{
#ifdef LINEARUI_SET_CURRENT_CONTEXT_FUNC
    LINEARUI_SET_CURRENT_CONTEXT_FUNC(ctx); // For custom thread-based hackery you may want to have control over this.
#else
    GLinearUI = ctx;
#endif
}

void LinearUI::SetAllocatorFunctions(LinearUIMemAllocFunc alloc_func, LinearUIMemFreeFunc free_func, void* user_data)
{
    GImAllocatorAllocFunc = alloc_func;
    GImAllocatorFreeFunc = free_func;
    GImAllocatorUserData = user_data;
}

// This is provided to facilitate copying allocators from one static/DLL boundary to another (e.g. retrieve default allocator of your executable address space)
void LinearUI::GetAllocatorFunctions(LinearUIMemAllocFunc* p_alloc_func, LinearUIMemFreeFunc* p_free_func, void** p_user_data)
{
    *p_alloc_func = GImAllocatorAllocFunc;
    *p_free_func = GImAllocatorFreeFunc;
    *p_user_data = GImAllocatorUserData;
}

LinearUIContext* LinearUI::CreateContext(LinearFontAtlas* shared_font_atlas)
{
    LinearUIContext* prev_ctx = GetCurrentContext();
    LinearUIContext* ctx = LINEARUI_NEW(LinearUIContext)(shared_font_atlas);
    SetCurrentContext(ctx);
    Initialize();
    if (prev_ctx != NULL)
        SetCurrentContext(prev_ctx); // Restore previous context if any, else keep new one.
    return ctx;
}

void LinearUI::DestroyContext(LinearUIContext* ctx)
{
    LinearUIContext* prev_ctx = GetCurrentContext();
    if (ctx == NULL) //-V1051
        ctx = prev_ctx;
    SetCurrentContext(ctx);
    Shutdown();
    SetCurrentContext((prev_ctx != ctx) ? prev_ctx : NULL);
    LINEARUI_DELETE(ctx);
}

