static LinearDrawList* GetViewportBgFgDrawList(LinearUIViewportP* viewport, size_t drawlist_no, const char* drawlist_name)
{
    // Create the draw list on demand, because they are not frequently used for all viewports
    LinearUIContext& g = *GLinearUI;
    LINEARUI_ASSERT(drawlist_no < LINEARUI_COUNTOF(viewport->BgFgDrawLists));
    LinearDrawList* draw_list = viewport->BgFgDrawLists[drawlist_no];
    if (draw_list == NULL)
    {
        draw_list = LINEARUI_NEW(LinearDrawList)(&g.DrawListSharedData);
        draw_list->_OwnerName = drawlist_name;
        viewport->BgFgDrawLists[drawlist_no] = draw_list;
    }

    // Our LinearDrawList system requires that there is always a command
    if (viewport->BgFgDrawListsLastTimeActive[drawlist_no] != (float)g.Time)
    {
        draw_list->_ResetForNewFrame();
        draw_list->PushTexture(g.IO.Fonts->TexRef);
        draw_list->PushClipRect(viewport->Pos, viewport->Pos + viewport->Size, false);
        viewport->BgFgDrawListsLastTimeActive[drawlist_no] = (float)g.Time;
    }
    return draw_list;
}

LinearDrawList* LinearUI::GetBackgroundDrawList(LinearUIViewport* viewport)
{
    if (viewport == NULL)
        viewport = GLinearUI->CurrentWindow->Viewport;
    return GetViewportBgFgDrawList((LinearUIViewportP*)viewport, 0, "##Background");
}

