void LinearUI::SetWindowSize(LinearUIWindow* window, const LinearVec2& size, LinearUICond cond)
{
    // Test condition (NB: bit 0 is always true) and clear flags for next time
    if (cond && (window->SetWindowSizeAllowFlags & cond) == 0)
        return;

    LINEARUI_ASSERT(cond == 0 || LinearIsPowerOfTwo(cond)); // Make sure the user doesn't attempt to combine multiple condition flags.
    window->SetWindowSizeAllowFlags &= ~(LinearUICond_Once | LinearUICond_FirstUseEver | LinearUICond_Appearing);

    // Enable auto-fit (not done in BeginChild() path unless appearing or combined with LinearUIChildFlags_AlwaysAutoResize)
    if ((window->Flags & LinearUIWindowFlags_ChildWindow) == 0 || window->Appearing || (window->ChildFlags & LinearUIChildFlags_AlwaysAutoResize) != 0)
        window->AutoFitFramesX = (size.x <= 0.0f) ? 2 : 0;
    if ((window->Flags & LinearUIWindowFlags_ChildWindow) == 0 || window->Appearing || (window->ChildFlags & LinearUIChildFlags_AlwaysAutoResize) != 0)
        window->AutoFitFramesY = (size.y <= 0.0f) ? 2 : 0;

    // Set
    LinearVec2 old_size = window->SizeFull;
    if (size.x <= 0.0f)
        window->AutoFitOnlyGrows = false;
    else
        window->SizeFull.x = LINEARUI_TRUNC(size.x);
    if (size.y <= 0.0f)
        window->AutoFitOnlyGrows = false;
    else
        window->SizeFull.y = LINEARUI_TRUNC(size.y);
    if (old_size.x != window->SizeFull.x || old_size.y != window->SizeFull.y)
        MarkIniSettingsDirty(window);
}

