void LinearUI::SetNextWindowPos(const LinearVec2& pos, LinearUICond cond, const LinearVec2& pivot)
{
    LinearUIContext& g = *GLinearUI;
    LINEARUI_ASSERT(cond == 0 || LinearIsPowerOfTwo(cond)); // Make sure the user doesn't attempt to combine multiple condition flags.
    g.NextWindowData.HasFlags |= LinearUINextWindowDataFlags_HasPos;
    g.NextWindowData.PosVal = pos;
    g.NextWindowData.PosPivotVal = pivot;
    g.NextWindowData.PosCond = cond ? cond : LinearUICond_Always;
    g.NextWindowData.PosUndock = true;
}

void LinearUI::SetNextWindowSize(const LinearVec2& size, LinearUICond cond)
{
    LinearUIContext& g = *GLinearUI;
    LINEARUI_ASSERT(cond == 0 || LinearIsPowerOfTwo(cond)); // Make sure the user doesn't attempt to combine multiple condition flags.
    g.NextWindowData.HasFlags |= LinearUINextWindowDataFlags_HasSize;
    g.NextWindowData.SizeVal = size;
    g.NextWindowData.SizeCond = cond ? cond : LinearUICond_Always;
}

// For each axis:
// - Use 0.0f as min or FLT_MAX as max if you don't want limits, e.g. size_min = (500.0f, 0.0f), size_max = (FLT_MAX, FLT_MAX) sets a minimum width.
// - Use -1 for both min and max of same axis to preserve current size which itself is a constraint.
// - See "Demo->Examples->Constrained-resizing window" for examples.
void LinearUI::SetNextWindowSizeConstraints(const LinearVec2& size_min, const LinearVec2& size_max, LinearUISizeCallback custom_callback, void* custom_callback_user_data)
{
    LinearUIContext& g = *GLinearUI;
    g.NextWindowData.HasFlags |= LinearUINextWindowDataFlags_HasSizeConstraint;
    g.NextWindowData.SizeConstraintRect = LinearRect(size_min, size_max);
    g.NextWindowData.SizeCallback = custom_callback;
    g.NextWindowData.SizeCallbackUserData = custom_callback_user_data;
}

