void LinearUI::PushFocusScope(LinearUIID id)
{
    LinearUIContext& g = *GLinearUI;
    LinearUIFocusScopeData data;
    data.ID = id;
    data.WindowID = g.CurrentWindow->ID;
    g.FocusScopeStack.push_back(data);
    g.CurrentFocusScopeId = id;
}

void LinearUI::PopFocusScope()
{
    LinearUIContext& g = *GLinearUI;
    LINEARUI_ASSERT_USER_ERROR_RET(g.FocusScopeStack.Size > g.StackSizesInBeginForCurrentWindow->SizeOfFocusScopeStack, "Calling PopFocusScope() too many times!");
    g.FocusScopeStack.pop_back();
    g.CurrentFocusScopeId = g.FocusScopeStack.Size ? g.FocusScopeStack.back().ID : 0;
}

bool LinearUI::IsInNavFocusRoute(LinearUIID focus_scope_id)
{
    LinearUIContext& g = *GLinearUI;
    if (g.NavFocusScopeId == focus_scope_id)
        return true;
    for (const LinearUIFocusScopeData& focus_scope : g.NavFocusRoute)
        if (focus_scope.ID == focus_scope_id)
            return true;
    return false;
}

void LinearUI::SetNavFocusScope(LinearUIID focus_scope_id)
{
    LinearUIContext& g = *GLinearUI;
    g.NavFocusScopeId = focus_scope_id;
    g.NavFocusRoute.resize(0); // Invalidate
    if (focus_scope_id == 0)
        return;
    LINEARUI_ASSERT(g.NavWindow != NULL);

    // Store current path (in reverse order)
    if (focus_scope_id == g.CurrentFocusScopeId)
    {
        // Top of focus stack contains local focus scopes inside current window
        for (int n = g.FocusScopeStack.Size - 1; n >= 0 && g.FocusScopeStack.Data[n].WindowID == g.CurrentWindow->ID; n--)
            g.NavFocusRoute.push_back(g.FocusScopeStack.Data[n]);
    }
    else if (focus_scope_id == g.NavWindow->NavRootFocusScopeId)
        g.NavFocusRoute.push_back({ focus_scope_id, g.NavWindow->ID });
    else
        return;

    // Then follow on manually set ParentWindowForFocusRoute field (#6798)
    for (LinearUIWindow* window = g.NavWindow->ParentWindowForFocusRoute; window != NULL; window = window->ParentWindowForFocusRoute)
        g.NavFocusRoute.push_back({ window->NavRootFocusScopeId, window->ID });
    LINEARUI_ASSERT(g.NavFocusRoute.Size < 100); // Maximum depth is technically 251 as per CalcRoutingScore(): 254 - 3
}

// Focus = move navigation cursor, set scrolling, set focus window.
void LinearUI::FocusItem()
{
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;
    LINEARUI_DEBUG_LOG_FOCUS("FocusItem(0x%08x) in window \"%s\"\n", g.LastItemData.ID, window->Name);
    if (g.DragDropActive || g.MovingWindow != NULL) // FIXME: Opt-in flags for this?
    {
        LINEARUI_DEBUG_LOG_FOCUS("FocusItem() ignored while DragDropActive!\n");
        return;
    }

    LinearUINavMoveFlags move_flags = LinearUINavMoveFlags_IsTabbing | LinearUINavMoveFlags_FocusApi | LinearUINavMoveFlags_NoSetNavCursorVisible | LinearUINavMoveFlags_NoSelect;
    LinearUIScrollFlags scroll_flags = window->Appearing ? LinearUIScrollFlags_KeepVisibleEdgeX | LinearUIScrollFlags_AlwaysCenterY : LinearUIScrollFlags_KeepVisibleEdgeX | LinearUIScrollFlags_KeepVisibleEdgeY;
    SetNavWindow(window);
    NavMoveRequestSubmit(LinearUIDir_None, LinearUIDir_Up, move_flags, scroll_flags);
    NavMoveRequestResolveWithLastItem(&g.NavMoveResultLocal);
}

void LinearUI::ActivateItemByID(LinearUIID id)
{
    LinearUIContext& g = *GLinearUI;
    g.NavNextActivateId = id;
    g.NavNextActivateFlags = LinearUIActivateFlags_None;
}

// Note: this will likely be called ActivateItem() once we rework our Focus/Activation system!
// But ActivateItem() should function without altering scroll/focus?
void LinearUI::SetKeyboardFocusHere(int offset)
{
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;
    LINEARUI_ASSERT(offset >= -1);    // -1 is allowed but not below
    LINEARUI_DEBUG_LOG_FOCUS("SetKeyboardFocusHere(%d) in window \"%s\"\n", offset, window->Name);

    // It makes sense in the vast majority of cases to never interrupt a drag and drop.
    // When we refactor this function into ActivateItem() we may want to make this an option.
    // MovingWindow is protected from most user inputs using SetActiveIdUsingNavAndKeys(), but
    // is also automatically dropped in the event g.ActiveId is stolen.
    if (g.DragDropActive || g.MovingWindow != NULL)
    {
        LINEARUI_DEBUG_LOG_FOCUS("SetKeyboardFocusHere() ignored while DragDropActive!\n");
        return;
    }

    SetNavWindow(window);

    LinearUINavMoveFlags move_flags = LinearUINavMoveFlags_IsTabbing | LinearUINavMoveFlags_Activate | LinearUINavMoveFlags_FocusApi | LinearUINavMoveFlags_NoSetNavCursorVisible;
    LinearUIScrollFlags scroll_flags = window->Appearing ? LinearUIScrollFlags_KeepVisibleEdgeX | LinearUIScrollFlags_AlwaysCenterY : LinearUIScrollFlags_KeepVisibleEdgeX | LinearUIScrollFlags_KeepVisibleEdgeY;
    NavMoveRequestSubmit(LinearUIDir_None, offset < 0 ? LinearUIDir_Up : LinearUIDir_Down, move_flags, scroll_flags); // FIXME-NAV: Once we refactor tabbing, add LegacyApi flag to not activate non-inputable.
    if (offset == -1)
    {
        NavMoveRequestResolveWithLastItem(&g.NavMoveResultLocal);
    }
    else
    {
        g.NavTabbingDir = 1;
        g.NavTabbingCounter = offset + 1;
    }
}

void LinearUI::SetItemDefaultFocus()
{
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;
    if (!window->Appearing)
        return;
    if (g.NavWindow != window->RootWindowForNav || (!g.NavInitRequest && g.NavInitResult.ID == 0) || g.NavLayer != window->DC.NavLayerCurrent)
        return;

    g.NavInitRequest = false;
    NavApplyItemToResult(&g.NavInitResult);
    NavUpdateAnyRequestFlag();

    // Scroll could be done in NavInitRequestApplyResult() via an opt-in flag (we however don't want regular init requests to scroll)
    if (!window->ClipRect.Contains(g.LastItemData.Rect))
        ScrollToRectEx(window, g.LastItemData.Rect, LinearUIScrollFlags_None);
}

