// Push a given id value ignoring the ID stack as a seed.
void LinearUI::PushOverrideID(LinearUIID id)
{
    LinearUIContext& g = *GLinearUI;
    LinearUIWindow* window = g.CurrentWindow;
#ifndef LINEARUI_DISABLE_DEBUG_TOOLS
    if (g.DebugHookIdInfoId == id)
        DebugHookIdInfo(id, LinearUIDataType_ID, NULL, NULL);
#endif
    window->IDStack.push_back(id);
}

// Helper to avoid a common series of PushOverrideID -> GetID() -> PopID() call
// (note that when using this pattern, ID Stack Tool will tend to not display the intermediate stack level.
//  for that to work we would need to do PushOverrideID() -> ItemAdd() -> PopID() which would alter widget code a little more)
LinearUIID LinearUI::GetIDWithSeed(const char* str, const char* str_end, LinearUIID seed)
{
    LinearUIID id = LinearHashStr(str, str_end ? (str_end - str) : 0, seed);
#ifndef LINEARUI_DISABLE_DEBUG_TOOLS
    LinearUIContext& g = *GLinearUI;
    if (g.DebugHookIdInfoId == id)
        DebugHookIdInfo(id, LinearUIDataType_String, str, str_end);
#endif
    return id;
}

LinearUIID LinearUI::GetIDWithSeed(int n, LinearUIID seed)
{
    LinearUIID id = LinearHashData(&n, sizeof(n), seed);
#ifndef LINEARUI_DISABLE_DEBUG_TOOLS
    LinearUIContext& g = *GLinearUI;
    if (g.DebugHookIdInfoId == id)
        DebugHookIdInfo(id, LinearUIDataType_S32, (void*)(intptr_t)n, NULL);
#endif
    return id;
}

void LinearUI::PopID()
{
    LinearUIWindow* window = GLinearUI->CurrentWindow;
    LINEARUI_ASSERT_USER_ERROR_RET(window->IDStack.Size > 1, "Calling PopID() too many times!");
    window->IDStack.pop_back();
}

