static LinearUIKeyChord GetModForLRModKey(LinearUIKey key)
{
    if (key == LinearUIKey_LeftCtrl || key == LinearUIKey_RightCtrl)
        return LinearUIMod_Ctrl;
    if (key == LinearUIKey_LeftShift || key == LinearUIKey_RightShift)
        return LinearUIMod_Shift;
    if (key == LinearUIKey_LeftAlt || key == LinearUIKey_RightAlt)
        return LinearUIMod_Alt;
    if (key == LinearUIKey_LeftSuper || key == LinearUIKey_RightSuper)
        return LinearUIMod_Super;
    return LinearUIMod_None;
}

LinearUIKeyChord LinearUI::FixupKeyChord(LinearUIKeyChord key_chord)
{
    // Add LinearUIMod_XXXX when a corresponding LinearUIKey_LeftXXX/LinearUIKey_RightXXX is specified.
    LinearUIKey key = (LinearUIKey)(key_chord & ~LinearUIMod_Mask_);
    if (IsLRModKey(key))
        key_chord |= GetModForLRModKey(key);
    return key_chord;
}

LinearUIKeyData* LinearUI::GetKeyData(LinearUIContext* ctx, LinearUIKey key)
{
    LinearUIContext& g = *ctx;

    // Special storage location for mods
    if (key & LinearUIMod_Mask_)
        key = ConvertSingleModFlagToKey(key);

    LINEARUI_ASSERT(IsNamedKey(key) && "Support for user key indices was dropped in favor of LinearUIKey. Please update backend & user code.");
    return &g.IO.KeysData[key - LinearUIKey_NamedKey_BEGIN];
}

